/* FUNCTION ************************************************************************************************************
 *
 * Function Name : BOARD_InitTrustZone
 * Description   :
 *
 * END ****************************************************************************************************************/

/***********************************************************************************************************************
 * BOARD_InitTrustZone function
 **********************************************************************************************************************/
void BOARD_InitTrustZone()
{
    /* SAU configuration */

    /* Set SAU Control register: Disable SAU and All Secure */
    SAU->CTRL = 0;

    /* Set SAU region number */
    SAU->RNR = 0;
    /* Region base address */
    SAU->RBAR = SAU_REGION_0_BASE & SAU_RBAR_BADDR_Msk;
    /* Region end address */
    SAU->RLAR = (SAU_REGION_0_END & SAU_RLAR_LADDR_Msk) | ((0U << SAU_RLAR_NSC_Pos) & SAU_RLAR_NSC_Msk) |
                ((1U << SAU_RLAR_ENABLE_Pos) & SAU_RLAR_ENABLE_Msk);

    /* Set SAU region number */
    SAU->RNR = 1;
    /* Region base address */
    SAU->RBAR = SAU_REGION_1_BASE & SAU_RBAR_BADDR_Msk;
    /* Region end address */
    SAU->RLAR = (SAU_REGION_1_END & SAU_RLAR_LADDR_Msk) | ((0U << SAU_RLAR_NSC_Pos) & SAU_RLAR_NSC_Msk) |
                ((1U << SAU_RLAR_ENABLE_Pos) & SAU_RLAR_ENABLE_Msk);

    /* Set SAU region number */
    SAU->RNR = 2;
    /* Region base address */
    SAU->RBAR = SAU_REGION_2_BASE & SAU_RBAR_BADDR_Msk;
    /* Region end address */
    SAU->RLAR = (SAU_REGION_2_END & SAU_RLAR_LADDR_Msk) | ((1U << SAU_RLAR_NSC_Pos) & SAU_RLAR_NSC_Msk) |
                ((1U << SAU_RLAR_ENABLE_Pos) & SAU_RLAR_ENABLE_Msk);

    /* Force memory writes before continuing */
    __DSB();
    /* Flush and refill pipeline with updated permissions */
    __ISB();

    /* Set SAU Control register: Enable SAU and All Secure (applied only if disabled) */
    SAU->CTRL = ((0U << SAU_CTRL_ALLNS_Pos) & SAU_CTRL_ALLNS_Msk) | ((1U << SAU_CTRL_ENABLE_Pos) & SAU_CTRL_ENABLE_Msk);

    /* AHB configuration */

    /*--------------------------------------------------------------------
     - Flash Configuration (based on physical address 0x00000000)
     -------------------------------------------------------------------*/
    /* FLASH00_MEM_RULE: 0x00000000 - 0x0001FFFF (128KB)
     * Each register controls 8 rules x 4KB = 32KB. Value 0x3 per nibble = Secure Privileged.
     * All 4 registers cover the 128KB secure flash region.
     */
    AHBSC->FLASH00_MEM_RULE[0] = 0x33333333U; /* Rules 0-7:  0x00000000-0x00007FFF Secure Privileged */
    AHBSC->FLASH00_MEM_RULE[1] = 0x33333333U; /* Rules 8-15: 0x00008000-0x0000FFFF Secure Privileged */
    AHBSC->FLASH00_MEM_RULE[2] = 0x33333333U; /* Rules 16-23:0x00010000-0x00017FFF Secure Privileged */
    /* Rule 31 (bits[31:28]=0x0) = NS User: physical 0x0001F000-0x0001FFFF holds the NSC veneer table
     * at 0x0001FE00; NS code must be able to fetch the CMSE SG gateway here. Rules 24-30 remain S_PRIV. */
    AHBSC->FLASH00_MEM_RULE[3] = 0x03333333U; /* Rules 24-30:0x00018000-0x0001EFFF S_PRIV; Rule 31 NS User */

    /* FLASH01_MEM_RULE: Non-Secure (NS code region + Flash bank 1)
     * All Non-Secure User.
     */
    AHBSC->FLASH01_MEM_RULE[0] = 0x00000000U;
    AHBSC->FLASH01_MEM_RULE[1] = 0x00000000U;
    AHBSC->FLASH01_MEM_RULE[2] = 0x00000000U;
    AHBSC->FLASH01_MEM_RULE[3] = 0x00000000U;

    /* Flash IFR - Non-Secure */
    AHBSC->FLASH02_MEM_RULE = 0x00000000U;
    AHBSC->FLASH03_MEM_RULE = 0x00000000U;

    /*--------------------------------------------------------------------
     - ROM Configuration
     -------------------------------------------------------------------*/
    AHBSC->ROM_MEM_RULE[0] = 0x00000000U; /* Non-Secure User */
    AHBSC->ROM_MEM_RULE[1] = 0x00000000U;
    AHBSC->ROM_MEM_RULE[2] = 0x00000000U;
    AHBSC->ROM_MEM_RULE[3] = 0x00000000U;

    /*--------------------------------------------------------------------
     - SRAMX Configuration (0x04000000 - 0x04007FFF, 32KB)
     - Used for Non-Secure side
     -------------------------------------------------------------------*/
    AHBSC->RAMX_MEM_RULE[0] = 0x00000000U; /* NS User */
    AHBSC->RAMX_MEM_RULE[1] = 0x00000000U;
    AHBSC->RAMX_MEM_RULE[2] = 0x00000000U;
    AHBSC->RAMX_MEM_RULE[3] = 0x00000000U;

    /*--------------------------------------------------------------------
     - SRAMA Configuration (physical 0x20000000, S-alias 0x30000000, 32KB)
     - All of SRAMA is Secure Privileged.
     - RAMA_MEM_RULE[1] rules 0-3 also Secure Privileged: the linker places
     - secure stack/data at 0x30004000-0x3000BFFF which extends 16KB into
     - SRAMB (physical 0x20008000-0x2000BFFF); those rules must be S Priv.
     -------------------------------------------------------------------*/
    AHBSC->RAMA_MEM_RULE[0] = 0x33333333U; /* SRAMA rules 0-7: all Secure Privileged */
    AHBSC->RAMA_MEM_RULE[1] = 0x00003333U; /* SRAMB rules 0-3 (0x20008000-0x2000BFFF) S Priv, rules 4-7 NS */
    AHBSC->RAMA_MEM_RULE[2] = 0x00000000U; /* Non-Secure */
    AHBSC->RAMA_MEM_RULE[3] = 0x00000000U;
    AHBSC->RAMA_MEM_RULE[4] = 0x00000000U;
    AHBSC->RAMA_MEM_RULE[5] = 0x00000000U;
    AHBSC->RAMA_MEM_RULE[6] = 0x00000000U;
    AHBSC->RAMA_MEM_RULE[7] = 0x00000000U;

    /*--------------------------------------------------------------------
     - RAMB_MEM_RULE covers SRAMF/SRAMG/SRAMH (physical ~0x20040000+), all NS
     -------------------------------------------------------------------*/
    AHBSC->RAMB_MEM_RULE[0] = 0x00000000U;
    AHBSC->RAMB_MEM_RULE[1] = 0x00000000U;
    AHBSC->RAMB_MEM_RULE[2] = 0x00000000U;
    AHBSC->RAMB_MEM_RULE[3] = 0x00000000U;
    AHBSC->RAMB_MEM_RULE[4] = 0x00000000U;
    AHBSC->RAMB_MEM_RULE[5] = 0x00000000U;
    AHBSC->RAMB_MEM_RULE[6] = 0x00000000U;
    AHBSC->RAMB_MEM_RULE[7] = 0x00000000U;

    /*--------------------------------------------------------------------
     - Peripheral Configuration (according to YAML config, most are NS User)
     -------------------------------------------------------------------*/
    AHBSC->APB_PERIPHERAL_GROUP0_MEM_RULE0 = 0x00000000U;
    AHBSC->APB_PERIPHERAL_GROUP0_MEM_RULE1 = 0x00000000U;

    AHBSC->AIPS_BRIDGE_GROUP0_MEM_RULE0 = 0x00000000U;
    AHBSC->AIPS_BRIDGE_GROUP0_MEM_RULE1 = 0x00000000U;

    AHBSC->AIPS_BRIDGE_GROUP1_MEM_RULE0 = 0x00000000U;
    AHBSC->AIPS_BRIDGE_GROUP1_MEM_RULE1 = 0x00000000U;

    AHBSC->AIPS_BRIDGE_GROUP2_MEM_RULE0  = 0x00000000U;
    AHBSC->AIPS_BRIDGE_GROUP2_MEM_RULE1  = 0x00000000U;
    AHBSC->AIPS_BRIDGE_GROUP2_MEM_RULE2  = 0x00000000U;
    AHBSC->AIPS_BRIDGE_GROUP2_MEM_RULE3  = 0x00000000U;
    AHBSC->AIPS_BRIDGE_GROUP2_MEM_RULE4  = 0x00000000U;
    AHBSC->AIPS_BRIDGE_GROUP2_MEM_RULE5  = 0x00000000U;
    AHBSC->AIPS_BRIDGE_GROUP2_MEM_RULE6  = 0x00000000U;
    AHBSC->AIPS_BRIDGE_GROUP2_MEM_RULE7  = 0x00000000U;
    AHBSC->AIPS_BRIDGE_GROUP2_MEM_RULE8  = 0x00000000U;
    AHBSC->AIPS_BRIDGE_GROUP2_MEM_RULE9  = 0x00000000U;
    AHBSC->AIPS_BRIDGE_GROUP2_MEM_RULE10 = 0x00000000U;
    AHBSC->AIPS_BRIDGE_GROUP2_MEM_RULE11 = 0x00000000U;
    AHBSC->AIPS_BRIDGE_GROUP2_MEM_RULE12 = 0x00000000U;
    AHBSC->AIPS_BRIDGE_GROUP2_MEM_RULE13 = 0x00000000U;

    /* AHBSC itself and its 3 aliases set to Secure Privileged (rules 0-3 = 0x3) */
    AHBSC->AHB_SECURE_CTRL_MEM_RULE0 = 0x00003333U;

    /*--------------------------------------------------------------------
     - Master Security Level Configuration
     -------------------------------------------------------------------*/
    /* According to YAML: DMA0, DMA1, PKC, ENET0, USB1 etc. set to NS User */
    AHBSC->MASTER_SEC_LEVEL        = (AHBSC->MASTER_SEC_LEVEL & 0x3FFFFFFFU) | 0x80000000U;
    AHBSC->MASTER_SEC_ANTI_POL_REG = (AHBSC->MASTER_SEC_ANTI_POL_REG & 0x3FFFFFFFU) | 0x80000000U;

    /*--------------------------------------------------------------------
     - Interrupt Configuration (according to YAML, all Secure)
     -------------------------------------------------------------------*/
    NVIC->ITNS[0] = 0x00000000U; /* All interrupts Secure */
    NVIC->ITNS[1] = 0x00000000U;
    NVIC->ITNS[2] = 0x00000000U;
    NVIC->ITNS[3] = 0x00000000U;
    NVIC->ITNS[4] = 0x00000000U;

    /*--------------------------------------------------------------------
     - Global Options
     -------------------------------------------------------------------*/
    SCB->AIRCR = (SCB->AIRCR & 0x00009FF7U) | 0x05FA0000U;
    SCB->SCR &= 0xFFFFFFF7U;
    SCB->SHCSR &= 0xFFF7FFFFU;
    SCB->CPACR    = 0x00500005U;
    SCB->NSACR    = 0x00000C03U;
    SCnSCB->CPPWR = 0;

    /*--------------------------------------------------------------------
     - AHBSC Control Registers
     -------------------------------------------------------------------*/
    /* ENABLE_SECURE_CHECKING (bits[3:2]) must be DISABLED (0b10) on MCXA287.
     * With ENABLE_SECURE_CHECKING=1, AHBSC blocks secure-CPU data reads to
     * NS-configured flash (FLASH01), causing a PRECISERR HardFault when
     * TZM_JumpToNormalWorld reads the NS vector table at 0x00020000.
     * DISABLE_STRICT_MODE (bits[11:10]=0b01) and IDAU active (bits[15:14]=0b10)
     * are kept. SAU enforces the NS/S boundary at the CPU level.
     * 0x86A6->0x86AA: bits[3:2] 0b01->0b10 (secure checking disabled).
     */
    AHBSC->MISC_CTRL_REG    = 0x000086AAU;
    AHBSC->MISC_CTRL_DP_REG = 0x000086AAU;

    /* Lock CPU0 configuration */
    AHBSC->CPU0_LOCK_REG = 0x800002AAU;

    /* Memory barriers */
    __DSB();
    __ISB();
}

/***********************************************************************************************************************
 * BOARD_InitBootTEE function
 **********************************************************************************************************************/
void BOARD_InitBootTEE()
{
    BOARD_InitTrustZone();
}
